            bagTag, bag.nextLegIndex());
    for (int i = 0; i < newLegs.size(); i++) {
        LegRow leg = newLegs.get(i);
        jdbcTemplate.update(
                "INSERT INTO bag_itinerary (bag_tag, seq, leg_id, origin, destination) VALUES (?, ?, ?, ?, ?)",
