        Integer domVersion = jdbcTemplate.queryForObject(
                "SELECT version FROM leg WHERE leg_id = 'NEW_DOM'", Integer.class);
        assertThat(domVersion).isEqualTo(2);

        // 封舱后不可改派
        registerBag("BAG2", List.of("NEW_DOM"));
